mapper.select:
SELECT h.id, h.product_id, p.name, p.cover_url, p.price, p.stock, h.viewed_at, p.category_id FROM product_browse_history h JOIN product p ON h.product_id = p.id WHERE h.user_id = #{userId}
AND p.name LIKE CONCAT('%', #{keyword}, '%')
AND p.category_id = #{categoryId}
ORDER BY h.viewed_at DESC

mapper.delete:
DELETE FROM product_browse_history
WHERE user_id = #{userId}
  AND viewed_at < (
    SELECT viewed_at FROM (
                              SELECT viewed_at
                              FROM product_browse_history
                              WHERE user_id = #{userId}
                              ORDER BY viewed_at DESC
                              LIMIT 1 OFFSET #{max}
                          ) t
)
